    $pdf=(string)wc_get_order($id)->get_meta('_petshop_ppk_pdf'); if($pdf&&file_exists($pdf)){ $o['pdf']=array('f'=>basename($pdf),'b'=>filesize($pdf),'b64'=>base64_encode(file_get_contents($pdf))); }
