    $r=$G(admin_url('admin.php?page=ps-desk&view=saskaitos&t=ppk')); $h=(string)wp_remote_retrieve_body($r); $o['saskaitos_ppk']=array('code'=>wp_remote_retrieve_response_code($r),'eil'=>preg_match_all('/<tr><td>(.*?)<\/td><td><b>(.*?)<\/b><\/td><td>(.*?)<\/td>/su',$h,$mm)?array_map(function($a,$b,$c){return "$a $b $c";},$mm[1],$mm[2],$mm[3]):array(),'foot'=>preg_match('/<tfoot>(.*?)<\/tfoot>/su',$h,$ft)?trim(preg_replace('/\s+/',' ',wp_strip_all_tags($ft[1]))):'','opt_kvitas'=>(int)preg_match('/<option value="ppk"/',$h),'h1'=>preg_match('/<h1 class="dl-h1">(.*?)<\/h1>/su',$h,$h1)?trim(wp_strip_all_tags($h1[1])):'');
